import struct
def get_jpg_size(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()
    i = 0
    while i < len(data):
        if data[i] == 0xFF:
            marker = data[i+1]
            if marker in (0xC0, 0xC1, 0xC2):
                h, w = struct.unpack('>HH', data[i+5:i+9])
                return w, h
            elif marker == 0xD8 or marker == 0xD9:
                i += 2
            else:
                length = struct.unpack('>H', data[i+2:i+4])[0]
                i += 2 + length
        else:
            i += 1
    return None
print('hero:', get_jpg_size('images/hero.jpg'))
print('about:', get_jpg_size('images/about.jpg'))
"

