const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

let html = fs.readFileSync('index.html', 'utf8');
const testFile = path.resolve(__dirname, 'temp_test.html');
const script = `
<script>
window.addEventListener('load', () => {
  const docWidth = document.documentElement.clientWidth;
  const overflows = [];
  document.querySelectorAll('*').forEach(el => {
    const rect = el.getBoundingClientRect();
    if (rect.right > docWidth + 0.5 || rect.left < -0.5) {
      overflows.push({ tag: el.tagName, class: el.className, id: el.id, left: rect.left, right: rect.right, width: rect.width, docWidth });
    }
  });
  console.log('OVERFLOWS:::' + JSON.stringify(overflows));
});
</script>
`;
fs.writeFileSync(testFile, html.replace('</body>', script + '</body>'));

try {
  const out = execSync(`"/c/Program Files (x86)/Microsoft/Edge/Application/msedge.exe" --headless=new --disable-gpu --virtual-time-budget=2000 --window-size=390,844 --enable-logging=stderr "file:///${testFile.replace(/\\\\/g, '/')}" 2>&1`, { encoding: 'utf8', timeout: 15000 });
  const m = out.match(/OVERFLOWS:::(.*)/);
  if (m) {
    console.log('Detected overflows:', m[1]);
  } else {
    console.log('Raw output:', out);
  }
} catch (e) {
  console.log('Err:', e.stdout || e.message);
} finally {
  if (fs.existsSync(testFile)) fs.unlinkSync(testFile);
}

