const http = require('http');
const { execSync } = require('child_process');
const fs = require('fs');

const server = http.createServer((req, res) => {
  if (req.method === 'POST') {
    let body = '';
    req.on('data', c => body += c);
    req.on('end', () => {
      console.log('CLIENT REPORT:', body);
      res.writeHead(200);
      res.end('ok');
    });
    return;
  }
  let html = fs.readFileSync('index.html', 'utf8');
  const inject = `
  <script>
  window.addEventListener('load', () => {
    const docWidth = document.documentElement.clientWidth;
    const overflows = [];
    document.querySelectorAll('*').forEach(el => {
      const rect = el.getBoundingClientRect();
      if (rect.right > docWidth + 0.5 || rect.left < -0.5) {
        overflows.push({ tag: el.tagName, class: el.className, id: el.id, left: Math.round(rect.left), right: Math.round(rect.right), width: Math.round(rect.width), docWidth });
      }
    });
    fetch('http://127.0.0.1:3456/', {
      method: 'POST',
      body: JSON.stringify({ docWidth, scrollWidth: document.documentElement.scrollWidth, overflows })
    });
  });
  </script>
  `;
  if (req.url.endsWith('.css')) {
    res.writeHead(200, {'Content-Type': 'text/css'});
    res.end(fs.readFileSync('css/style.css'));
  } else if (req.url.endsWith('.jpg')) {
    res.writeHead(200, {'Content-Type': 'image/jpeg'});
    res.end(fs.readFileSync(req.url.replace(/^\//, '')));
  } else {
    res.writeHead(200, {'Content-Type': 'text/html'});
    res.end(html.replace('</body>', inject + '</body>'));
  }
});

server.listen(3456, () => {
  const edgePath = '\"C:\\\\Program Files (x86)\\\\Microsoft\\\\Edge\\\\Application\\\\msedge.exe\"';
  try {
    execSync(`${edgePath} --headless=new --disable-gpu --virtual-time-budget=3000 --window-size=390,844 http://127.0.0.1:3456/`, { stdio: 'ignore', timeout: 10000 });
  } catch (e) {}
  setTimeout(() => server.close(), 1000);
});

