:root {
  --primary: #2d6a4f;
  --primary-hover: #1e4a36;
  --secondary: #b85d34;
  --accent: #f4ede4;
  --dark: #1b281f;
  --darker: #121c15;
  --bg-main: #fbf9f5;
  --bg-alt: #f4eee5;
  --card-bg: #ffffff;
  --text-main: #2b2d2f;
  --text-muted: #646a70;
  --border-color: rgba(45, 106, 79, 0.15);
}

*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 80px;
}

body {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--text-main);
  background-color: var(--bg-main);
  line-height: 1.65;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6,
.navbar-brand,
.display-heading,
.section-title,
.footer-brand {
  font-family: 'Cormorant Garamond', Garamond, 'Times New Roman', Georgia, serif;
  letter-spacing: -0.01em;
}

/* Navbar */
.navbar {
  background-color: var(--dark) !important;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.15);
  padding: 0.85rem 0;
  z-index: 1030;
}

.navbar-brand {
  color: #ffffff !important;
  font-size: 1.85rem;
  letter-spacing: 0.5px;
  font-weight: 700;
}

.nav-link {
  color: rgba(255, 255, 255, 0.85) !important;
  font-weight: 500;
  font-size: 0.95rem;
  letter-spacing: 0.3px;
  padding: 0.5rem 1rem !important;
  border-radius: 4px;
  transition: color 0.2s ease, background-color 0.2s ease;
}

.nav-link:hover,
.nav-link:focus {
  color: #ffffff !important;
  background-color: rgba(255, 255, 255, 0.08);
}

.navbar-toggler {
  border-color: rgba(255, 255, 255, 0.3);
  padding: 0.4rem 0.65rem;
}

.navbar-toggler:focus {
  box-shadow: 0 0 0 0.2rem rgba(255, 255, 255, 0.2);
}

@media (max-width: 991.98px) {
  .navbar-collapse {
    background-color: var(--dark);
    padding: 1rem 0.5rem;
    margin-top: 0.75rem;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
  }
  .navbar-nav .nav-item {
    margin-bottom: 0.25rem;
  }
}

/* Hero Section */
.hero-image-full {
  background-size: cover;
  background-position: center;
  position: relative;
  min-height: 480px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-overlay {
  background: linear-gradient(180deg, rgba(27, 40, 31, 0.78) 0%, rgba(27, 40, 31, 0.6) 100%);
  width: 100%;
  min-height: 480px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.display-heading {
  font-size: clamp(2.5rem, 6vw, 4.2rem);
  font-weight: 700;
  letter-spacing: 0.02em;
}

/* Buttons */
.btn-brand {
  background-color: var(--primary);
  border-color: var(--primary);
  color: #ffffff;
  font-weight: 600;
  border-radius: 6px;
  transition: all 0.2s ease-in-out;
}

.btn-brand:hover,
.btn-brand:focus {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
  color: #ffffff;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(45, 106, 79, 0.35);
}

/* About Section */
#about {
  background-color: var(--bg-main);
}

.section-title {
  color: var(--dark);
  font-size: clamp(2rem, 4vw, 2.75rem);
}

.tracking-wide {
  letter-spacing: 1.5px;
}

.badge-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background-color: var(--primary);
  color: #ffffff;
  font-size: 0.75rem;
  font-weight: bold;
  flex-shrink: 0;
}

.about-img {
  max-height: 420px;
  width: 100%;
  object-fit: cover;
  border: 1px solid rgba(0, 0, 0, 0.05);
}

/* Services Section */
.services-section {
  background-color: var(--bg-alt);
}

.card-service {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-top: 4px solid var(--primary);
  border-radius: 10px;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card-service:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.08) !important;
}

.service-title {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 1.05rem;
  color: var(--dark);
  line-height: 1.35;
}

/* Testimonials */
#testimonial {
  background-color: var(--bg-main);
}

.testimonial-card {
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  position: relative;
}

.quote-mark {
  font-family: 'Cormorant Garamond', serif;
  font-size: 4rem;
  line-height: 0.8;
  color: var(--primary);
  opacity: 0.35;
}

.testimonial-quote {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: clamp(1.25rem, 2.5vw, 1.6rem) !important;
  color: var(--dark);
  line-height: 1.5;
}

/* Contact Section */
.hero-dark {
  background-color: var(--dark);
  color: #ffffff;
}

/* Footer */
footer {
  background-color: var(--darker);
  color: #ffffff;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.footer-brand {
  font-size: 1.35rem;
  letter-spacing: 0.5px;
}

img {
  max-width: 100%;
  height: auto;
}
